import csv,json,re,collections,ast
rows=[]
with open('/tmp/autocuda-cost-corrected-rows.tsv') as f:
 for r in csv.DictReader(f,delimiter='\t'):
  if r['label'].startswith('brief-') or r['label'] in ('steered/brief-87-interrupted','steered/brief-88-interrupted','steered/brief-89-interrupted'):rows.append(r)

def extract(s,method):
 out=[]; needle='tools.'+method; pos=0
 while True:
  i=s.find(needle,pos)
  if i<0:break
  p=s.find('(',i+len(needle));
  if p<0:break
  depth=0; quote=None; esc=False; end=None
  for k in range(p,len(s)):
   c=s[k]
   if quote:
    if esc:esc=False
    elif c=='\\':esc=True
    elif c==quote:quote=None
   else:
    if c in "'\"`":quote=c
    elif c=='(':depth+=1
    elif c==')':
     depth-=1
     if depth==0:end=k+1;break
  if end is None:break
  out.append(s[i:end]);pos=end
 return out

def fieldnum(s,key):
 m=re.search(r'(?:["\']?'+re.escape(key)+r'["\']?)\s*:\s*([0-9]+)',s);return int(m.group(1)) if m else None

def strfield(s,key):
 m=re.search(r'(?:["\']?'+re.escape(key)+r'["\']?)\s*:\s*("(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')',s,re.S)
 if not m:return None
 lit=m.group(1)
 try:
  return json.loads(lit) if lit[0]=='"' else ast.literal_eval(lit)
 except:return lit[1:-1]
methods=collections.Counter(); yields=collections.defaultdict(collections.Counter); execs=[];writes=[]; outers=0
for r in rows:
 for i,l in enumerate(open(r['path']),1):
  if i<int(r['boundary_line']):continue
  j=json.loads(l);q=j.get('payload',{})
  if q.get('type')!='custom_tool_call' or q.get('name')!='exec':continue
  outers+=1;s=q.get('input','')
  for method in ('exec_command','write_stdin'):
   for c in extract(s,method):
    methods[method]+=1;yields[method][fieldnum(c,'yield_time_ms')]+=1
    if method=='exec_command':execs.append((r['label'],i,j['timestamp'],fieldnum(c,'yield_time_ms'),strfield(c,'cmd'),c))
    else:writes.append((r['label'],i,j['timestamp'],fieldnum(c,'yield_time_ms'),strfield(c,'session_id'),strfield(c,'chars'),fieldnum(c,'session_id'),c))
print('sessions',len(rows),'outer exec',outers,'nested',methods)
print('yield dists')
for k,v in yields.items():print(k,v)
print('exec commands missing',sum(x[4] is None for x in execs),'write sid missing',sum(x[6] is None for x in writes),'chars missing',sum(x[5] is None for x in writes))
# classify writes chars using source regex since strfield sid is numeric not str
charc=collections.Counter(); signals=[]
for x in writes:
 c=x[-1]; chars=strfield(c,'chars')
 if chars is None:charc['omitted']+=1
 elif chars=='':charc['empty']+=1
 else:
  charc[repr(chars)]+=1;signals.append(x)
print('write chars',charc)
print('write signals')
for x in signals[:50]:print(x[0],x[1],x[2],x[3],repr(strfield(x[-1],'chars')),x[-1][:300])
# command classify
cc=collections.Counter(); autocuda=collections.Counter(); tout=collections.Counter();poll=[]
for label,line,ts,y,cmd,raw in execs:
 cmd=cmd or ''
 if 'autocuda run slice' in cmd:cc['autocuda build slice']+=1
 elif 'autocuda run exclusive' in cmd:cc['autocuda exclusive']+=1
